+        throw new IllegalArgumentException("field [" + fieldName + "] is not a numeric type");
+    }
+
+    public MultiGeoPointValues getGeoPointField(String fieldName, LeafReaderContext ctx) {
+        ValuesSource valuesSource = getField(fieldName);
